import{_ as i,o as a,c as e,a3 as l}from"./chunks/framework.DACwFHq9.js";const r=JSON.parse('{"title":"依赖供应链安全检查","description":"","frontmatter":{},"headers":[],"relativePath":"guide/dependency-supply-chain-security.md","filePath":"guide/dependency-supply-chain-security.md","lastUpdated":1786065716000}'),n={name:"guide/dependency-supply-chain-security.md"};function t(p,s,h,d,o,c){return a(),e("div",null,[...s[0]||(s[0]=[l(`<h1 id="依赖供应链安全检查" tabindex="-1">依赖供应链安全检查 <a class="header-anchor" href="#依赖供应链安全检查" aria-label="Permalink to &quot;依赖供应链安全检查&quot;">​</a></h1><p>AIO Hub 在 Bun 安装流程前后执行本地依赖扫描，目标是尽早发现常见的依赖投毒特征。该检查是启发式防线，不替代代码审查、漏洞响应或依赖来源验证。</p><h2 id="默认防线" tabindex="-1">默认防线 <a class="header-anchor" href="#默认防线" aria-label="Permalink to &quot;默认防线&quot;">​</a></h2><h3 id="_1-安装前门禁" tabindex="-1">1. 安装前门禁 <a class="header-anchor" href="#_1-安装前门禁" aria-label="Permalink to &quot;1. 安装前门禁&quot;">​</a></h3><p>根 <code>package.json</code> 的 <code>preinstall</code> 会运行：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">bun</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> scripts/security/scan-dependencies.ts</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --mode</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> lock</span></span></code></pre></div><p>该模式不依赖 <code>node_modules</code>，检查：</p><ul><li>根包和 <code>bun.lock</code> 中登记的 workspace 清单；</li><li>Git、HTTP tarball、<code>file:</code>、<code>link:</code> 等非 registry 依赖来源；</li><li>npm alias 指向不同包名的情况；</li><li>自定义锁文件来源；</li><li>registry 包是否有有效的 SHA-512 完整性摘要；</li><li>本地禁用包清单。</li></ul><p>高危或严重命中会阻断安装。</p><h3 id="_2-生命周期脚本最小信任" tabindex="-1">2. 生命周期脚本最小信任 <a class="header-anchor" href="#_2-生命周期脚本最小信任" aria-label="Permalink to &quot;2. 生命周期脚本最小信任&quot;">​</a></h3><p>根 <code>package.json</code> 使用 <code>trustedDependencies</code> 明确列出允许执行安装生命周期脚本的包。目前仅允许项目构建实际需要的：</p><ul><li><code>@parcel/watcher</code></li><li><code>esbuild</code></li><li><code>vue-demi</code></li></ul><p>不要因为某个包提示脚本被阻止就直接加入清单。先确认包名和版本、检查其 <code>preinstall</code> / <code>install</code> / <code>postinstall</code> 内容，并说明为什么项目需要执行它。</p><p>查看被 Bun 阻止的脚本：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">bun</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> pm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> untrusted</span></span></code></pre></div><h3 id="_3-安装后实际内容扫描" tabindex="-1">3. 安装后实际内容扫描 <a class="header-anchor" href="#_3-安装后实际内容扫描" aria-label="Permalink to &quot;3. 安装后实际内容扫描&quot;">​</a></h3><p>根 <code>postinstall</code> 在运行项目自身的 Wry 补丁脚本前执行：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">bun</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> security:dependencies</span></span></code></pre></div><p>它会遍历 <code>node_modules/.bun</code> 中实际安装的包，重点检查安装生命周期命令及其引用文件，包括：</p><ul><li>下载内容后直接管道交给 shell；</li><li>PowerShell 编码命令、长编码载荷与动态执行组合；</li><li>读取 npm、GitHub、SSH、云凭据或完整环境变量并同时进行外部通信；</li><li>禁用 TLS 校验；</li><li>修改 shell 启动文件、计划任务、系统自启动位置；</li><li>写入 GitHub Actions workflow、调用 registry 发布/权限命令或凭据提取工具；</li><li>挖矿程序和矿池协议特征；</li><li><code>bin</code> 或生命周期脚本路径逃逸包目录；</li><li>普通联网下载器和进程执行组合。</li></ul><p>默认 <code>--fail-on high</code>：高危与严重问题阻断，常见二进制下载器等中风险行为只报告。人工审计时可使用严格模式：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">bun</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> security:dependencies:strict</span></span></code></pre></div><h3 id="_4-新版本冷却期" tabindex="-1">4. 新版本冷却期 <a class="header-anchor" href="#_4-新版本冷却期" aria-label="Permalink to &quot;4. 新版本冷却期&quot;">​</a></h3><p>根 <code>bunfig.toml</code> 将尚未锁定的新发布版本延迟 3 天进入解析范围。已有 <code>bun.lock</code> 版本不受影响。这样可以降低刚发布的恶意版本在告警、撤包和社区响应前被立即解析到的概率。</p><p>确有紧急升级需求时，可以把经过人工核验的包临时加入 <code>minimumReleaseAgeExcludes</code>，不要全局关闭冷却期。升级完成后应移除临时排除。</p><h3 id="_5-ci-锁文件冻结" tabindex="-1">5. CI 锁文件冻结 <a class="header-anchor" href="#_5-ci-锁文件冻结" aria-label="Permalink to &quot;5. CI 锁文件冻结&quot;">​</a></h3><p>工作流统一使用：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">bun</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --frozen-lockfile</span></span></code></pre></div><p>CI 不允许安装时静默改写解析结果。<code>check</code> 与 <code>check:ci</code> 也会再次运行安装后扫描。</p><h2 id="策略文件" tabindex="-1">策略文件 <a class="header-anchor" href="#策略文件" aria-label="Permalink to &quot;策略文件&quot;">​</a></h2><p>策略位于 <code>scripts/security/dependency-policy.json</code>：</p><div class="language-json vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;allowedNonRegistryDependencies&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: [],</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;allowedLockfileSources&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: [],</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;deniedPackages&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: [],</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;ignoredFindings&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: []</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><h3 id="允许非-registry-依赖" tabindex="-1">允许非 registry 依赖 <a class="header-anchor" href="#允许非-registry-依赖" aria-label="Permalink to &quot;允许非 registry 依赖&quot;">​</a></h3><p>值必须精确到“包名 + 完整 spec”，例如：</p><div class="language-json vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;allowedNonRegistryDependencies&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: [</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">    &quot;example-package@https://example.com/example-package-1.0.0.tgz&quot;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  ]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><p>只有在来源不可迁移到 registry、内容已经固定并经过审核时才允许。URL 应指向不可变内容，避免分支名或可覆盖资源。</p><h3 id="禁用包" tabindex="-1">禁用包 <a class="header-anchor" href="#禁用包" aria-label="Permalink to &quot;禁用包&quot;">​</a></h3><p>既可按包名禁用全部版本，也可精确到版本：</p><div class="language-json vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;deniedPackages&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: [</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;known-bad-package&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;compromised-package@1.2.3&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><p>确认投毒事件后，应优先删除依赖并重新生成锁文件；禁用清单用于阻止误加回仓库，不是修复手段。</p><h3 id="忽略规则命中" tabindex="-1">忽略规则命中 <a class="header-anchor" href="#忽略规则命中" aria-label="Permalink to &quot;忽略规则命中&quot;">​</a></h3><p>忽略项必须指定规则并填写非空理由，建议同时限制包名和版本：</p><div class="language-json vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;ignoredFindings&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: [</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    {</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">      &quot;ruleId&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;install-network-access&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">      &quot;package&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;reviewed-downloader&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">      &quot;version&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;1.2.3&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">      &quot;reason&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;固定地址下载已核验的官方平台二进制，升级版本时重新审核&quot;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    }</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  ]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><p>不要使用只写 <code>ruleId</code> 的宽泛忽略。包升级后应重新审核，避免旧结论自动覆盖新代码。</p><h2 id="漏洞审计" tabindex="-1">漏洞审计 <a class="header-anchor" href="#漏洞审计" aria-label="Permalink to &quot;漏洞审计&quot;">​</a></h2><p>本地行为扫描关注投毒与安装阶段行为；已公开漏洞使用 Bun 审计补充检查：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">bun</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> security:audit</span></span></code></pre></div><p>仓库当前可能存在来自开发工具或传递依赖的历史漏洞基线，因此该命令暂不作为安装门禁。处理审计结果时应区分：</p><ol><li>运行时可达的直接依赖；</li><li>仅测试、文档或打包环境可达的开发依赖；</li><li>有修复版本且可安全升级的传递依赖；</li><li>暂无上游修复、需要隔离或替换的依赖。</li></ol><h2 id="发现异常后的处理" tabindex="-1">发现异常后的处理 <a class="header-anchor" href="#发现异常后的处理" aria-label="Permalink to &quot;发现异常后的处理&quot;">​</a></h2><ol><li>立即停止运行新的安装脚本、开发服务器和构建命令。</li><li>保存扫描输出、可疑包名、版本、完整性摘要和锁文件 diff。</li><li>从干净环境撤销依赖变更，不要复用可能被污染的 <code>node_modules</code>。</li><li>如果脚本可能读取过环境变量或凭据，轮换 npm、GitHub、云平台、SSH 等相关密钥。</li><li>重新执行冻结安装、供应链扫描、相关测试和 Vite 构建。</li><li>将确认的恶意包加入 <code>deniedPackages</code>，并记录事件来源与处置结果。</li></ol><h2 id="已知边界" tabindex="-1">已知边界 <a class="header-anchor" href="#已知边界" aria-label="Permalink to &quot;已知边界&quot;">​</a></h2><ul><li>静态规则无法证明一个包安全，也可能对合法下载器产生中风险告警。</li><li>只检查安装生命周期入口及其直接引用脚本，不是对所有依赖源码的完整恶意代码分析。</li><li>已经执行过的恶意脚本不能靠事后扫描撤销，因此生命周期最小信任、冻结锁文件和冷却期同样重要。</li><li>私有 registry、Git 依赖和本地 tarball 默认需要显式审核与策略放行。</li></ul>`,53)])])}const u=i(n,[["render",t]]);export{r as __pageData,u as default};
